input.command:
cd D:\pal
$checks = @()
$tally = 'backend/app/integrations/tally/client.py','backend/app/integrations/tally/xml.py','backend/app/integrations/tally/parser.py','backend/app/integrations/tally/service.py','backend/app/integrations/tally/exceptions.py','backend/app/api/v1/tally/router.py','backend/app/services/tally_sync.py','backend/app/services/tally_mapping_sync.py','backend/app/services/voucher_posting.py','backend/app/models/tally_sync.py','backend/app/schemas/tally.py','src/lib/api/tally.ts','src/lib/queries/tally.ts','src/routes/tally.tsx','docs/tallyprime-poc.md'
$checks += [pscustomobject]@{name='fifteen_tally_integration_surfaces_present'; actual=@($tally | Where-Object { Test-Path $_ }).Count; expected=15}
$areas = 'backend/app/main.py','backend/app/models/voucher.py','backend/app/services/invoice_extraction.py','backend/app/services/bank_extraction.py','backend/app/services/ledger_suggestion.py','backend/app/services/voucher.py','backend/app/integrations/tally/service.py','src/lib/queries/tally.ts','backend/app/api/v1/router.py','backend/tests/conftest.py'
$checks += [pscustomobject]@{name='ten_focus_area_surfaces_present'; actual=@($areas | Where-Object { Test-Path $_ }).Count; expected=10}
$checks += [pscustomobject]@{name='head_unchanged_no_new_commit'; actual=[string](git rev-parse --short HEAD); expected='b2d3a58'}
$before = (git status --porcelain | Measure-Object -Line).Lines
Start-Sleep -Seconds 20
$after = (git status --porcelain | Measure-Object -Line).Lines
$checks += [pscustomobject]@{name='session_wrote_no_files_over_20s_idle_window'; actual=([int]$after - [int]$before); expected=0}
$pg = 0; $sock = New-Object System.Net.Sockets.TcpClient
try { $sock.Connect('127.0.0.1',5432); if ($sock.Connected) { $pg = 1 } } catch { $pg = 0 } finally { $sock.Close() }
$checks += [pscustomobject]@{name='user_provided_postgres_5432_reachable'; actual=$pg; expected=1}
$installs = 0
if (Test-Path 'C:\Program Files\PostgreSQL') { $installs++ }
if (Test-Path 'D:\pal\.pgdata') { $installs++ }
$checks += [pscustomobject]@{name='no_session_side_postgres_install_artifacts'; actual=$installs; expected=0}
Write-Output "detail before=$before after=$after"
$payload = [pscustomobject]@{version=1; checks=$checks}
Write-Output ('{"harnessVerification":' + (ConvertTo-Json -Compress -Depth 4 $payload) + '}')
